#!/usr/bin/env bash
# Проверка правила глушения `notifier_mute_decide` (тред 073, постановка curator
# 2026-09-02: «повторный отказ ОДНОГО и того же уведомителя не должен рождать
# письмо каждый раз»).
#
# Фикстура — каталог `messages/` треда-приёмника с письмами того вида, который
# кладёт сам смотритель: имя файла несёт время, тело — строку-ключ. Проверяется
# ровно то, что стоило девяти писем за тринадцать минут: ДВА ОДИНАКОВЫХ ОТКАЗА
# ПОДРЯД дают одно письмо, а не два.
#
# Прогон руками: bash .github/scripts/notifier-mute.test.sh
# В сьюте он же поднимается процессом (`src/roles/notifier-mute.process.test.ts`)
# — в отличие от `comms-push.test.sh`, оставленного ручным: там правило гоняется
# при правке файла, а здесь правило решает, поедет ли письмо, и молчаливо
# сломанное оно неотличимо от исправного.
set -uo pipefail

cd "$(dirname "$0")"
# shellcheck source=./notifier-mute.sh
source ./notifier-mute.sh

# ПРОБЫ С ТРЕМЯ ИСХОДАМИ (тред 186). До этого сверки этого файла писались формой
# `… && echo да || echo нет`, и двенадцать из них отвечали `нет` И на «правило нарушено»,
# И на «пробы не было вовсе» — отказ fork, SIGPIPE писателю конвейера, битый шаблон,
# отсутствующий файл, отсутствующая функция. Ровно так один такой ответ покрасил `main`
# в прогоне 34377052327 и не сказал о себе ничего. Разбор формы и замер — шапка `probe.sh`.
# shellcheck source=./probe.sh
source ./probe.sh

DIR="$(mktemp -d)"
trap 'rm -rf "$DIR"' EXIT
# Куда пробы кладут stderr: свой временный каталог, который убирает трап выше.
PROBE_STDERR="$DIR/probe-stderr.err"

FAILED=0
check() { # <что> <ожидалось> <получено>
  if [ "$2" = "$3" ]; then
    echo "ok   · $1"
    probe_stderr_reset
  else
    echo "FAIL · $1: ожидалось '$2', получено '$3'"
    # Вторая половина той же починки: несостоявшаяся проба объясняется в stderr, и до
    # этой строки он выбрасывался целиком (`2>/dev/null` у каждой второй сверки).
    probe_stderr_report
    FAILED=1
  fi
}

# --- 0. Контроль самих проб: три исхода различимы, и это ПРОВЕРЯЕТСЯ ----------
#
# Без этого раздела `probe.sh` был бы утверждением о себе — а он подключается ДВУМЯ
# скриптами и правится один раз на оба. Полный контроль всех четырёх проб живёт в
# `review-delivery.test.sh`, раздел 0; здесь стои́т тот минимум, который отвечает на
# вопрос «доехал ли до ЭТОГО скрипта рабочий probe.sh», плюс контроль мутации на форме,
# которая из этого файла и убрана.
check "проба: подстрока есть" "да" "$(grep_probe 'НЕ МЕНЕЕ 1' -F 'НЕ МЕНЕЕ')"
check "проба: подстроки нет" "нет" "$(grep_probe 'заглушать было нечего' -F 'НЕ МЕНЕЕ')"
check "проба: НЕСОСТОЯВШАЯСЯ проба названа кодом, а не выдана за «нет»" \
  "проба не состоялась (grep вышел кодом 2)" "$(grep_probe 'что угодно' -E '[')"
check "проба по коду: КОМАНДЫ НЕТ — это не «отказала», и код это говорит" "код 127" \
  "$(rc_probe нет-такой-команды-ни-в-каком-PATH)"
# КОНТРОЛЬ МУТАЦИИ: прежняя форма этого файла отвечает `нет` — то есть «правило верно» —
# на входе, где ничего не проверялось вовсе. Именно так двенадцать сверок ниже зеленели бы
# от ОТСУТСТВИЯ проверяемой функции.
check "контроль мутации: старая форма выдаёт отсутствие команды за ожидаемый отказ" "нет" \
  "$(нет-такой-команды-ни-в-каком-PATH >/dev/null 2>&1 && echo да || echo нет)"
MESSAGES="$DIR/messages"
mkdir -p "$MESSAGES"

letter() { # <метка в имени файла> <имя уведомителя>
  {
    printf '🔕 **Уведомитель `%s` отказал: `failure`.**\n\n' "$2"
    printf '%s · окно %s с\n' "$(notifier_mute_marker "$2")" "$NOTIFIER_MUTE_WINDOW_SEC"
  } > "$MESSAGES/$1-github.md"
}

# 1. Первый отказ — писать всегда: тред о нём ещё ничего не знает.
check "письма об уведомителе нет — письмо едет" \
  "deliver - -" "$(notifier_mute_decide "$MESSAGES" 'Comms Derived' '2026-09-02T16:39:00Z')"

# 2. ВТОРОЙ ОДИНАКОВЫЙ ОТКАЗ ПОДРЯД — тот самый случай петли: письмо уже лежит,
#    прошло полминуты. Ожидается глушение с названным возрастом.
letter '2026-09-02T16-39-00Z' 'Comms Derived'
check "повтор через 30 с — заглушён" \
  "mute 2026-09-02T16:39:00Z 30" "$(notifier_mute_decide "$MESSAGES" 'Comms Derived' '2026-09-02T16:39:30Z')"

# 3. Окно кончилось — письмо снова едет, и метка прошлого письма отдаётся
#    наружу: ею считается число заглушённых для громкой строки.
check "через 15 мин 1 с — письмо едет" \
  "deliver 2026-09-02T16:39:00Z 901" "$(notifier_mute_decide "$MESSAGES" 'Comms Derived' '2026-09-02T16:54:01Z')"
check "ровно на границе окна — письмо едет" \
  "deliver 2026-09-02T16:39:00Z 900" "$(notifier_mute_decide "$MESSAGES" 'Comms Derived' '2026-09-02T16:54:00Z')"

# 4. ДРУГОЙ уведомитель молчанием соседа не глушится: ключ — имя, и он различает.
check "другой уведомитель в том же окне — письмо едет" \
  "deliver - -" "$(notifier_mute_decide "$MESSAGES" 'Merge Notify' '2026-09-02T16:39:30Z')"

# 5. Из двух писем берётся ПОСЛЕДНЕЕ, а не первое попавшееся: серия в треде
#    длиннее одного письма, и решать по старшему значило бы разглушиться зря.
letter '2026-09-02T16-52-25Z' 'Comms Derived'
check "решает последнее письмо, а не первое" \
  "mute 2026-09-02T16:52:25Z 34" "$(notifier_mute_decide "$MESSAGES" 'Comms Derived' '2026-09-02T16:52:59Z')"

# 6. Отказ читается в сторону письма, а не тишины.
check "письмо из будущего (часы разъехались) — письмо едет" \
  "deliver 2026-09-02T16:52:25Z -145" "$(notifier_mute_decide "$MESSAGES" 'Comms Derived' '2026-09-02T16:50:00Z')"
check "пустой каталог — письмо едет" \
  "deliver - -" "$(notifier_mute_decide "$DIR/нет-такого" 'Comms Derived' '2026-09-02T16:39:30Z')"

# 7. Окно — параметр правила, а не константа внутри него: письмо той же
#    давности при коротком окне уже не глушится.
check "окно передано явно — правило считает по нему" \
  "deliver 2026-09-02T16:52:25Z 34" "$(notifier_mute_decide "$MESSAGES" 'Comms Derived' '2026-09-02T16:52:59Z' 10)"

# 8. ВЫБОР ЛЕНТЫ У СТОЯЧЕГО АДРЕСА (тред 080). Приёмник — не литерал: адрес
#    исполняют обычные треды по очереди, и правило обязано читать ленту того,
#    кто играет его СЕЙЧАС, иначе оно заглушит звонок серией из закрытого.
MAIL="$DIR/mail"
mkdir -p "$MAIL"
receiver() { # <id треда> <status>
  mkdir -p "$MAIL/$1/messages"
  printf -- '---\ntitle: Стоячий адрес\nparticipants: github, dev-core\nstatus: %s\n---\n' "$2" \
    > "$MAIL/$1/_meta.md"
}

check "приёмника у адреса нет вовсе — ленты нет, письмо поедет и откроет его" \
  "" "$(notifier_mute_source "$MAIL" 'notifier-down')"

receiver '077-notifier-down' open
check "единственный открытый приёмник — его лента" \
  "$MAIL/077-notifier-down/messages" "$(notifier_mute_source "$MAIL" 'notifier-down')"

# Старший по номеру, а не первый попавшийся: адрес переезжает вперёд.
receiver '104-notifier-down' open
check "открытых несколько — старший по номеру" \
  "$MAIL/104-notifier-down/messages" "$(notifier_mute_source "$MAIL" 'notifier-down')"

# ЗАКРЫТЫЙ ПРИЁМНИК ЛЕНТЫ НЕ ОТДАЁТ — ровно тот случай, ради которого функция и
# написана: письмо поедет в новый приёмник, а серия закрытого заглушила бы его.
receiver '104-notifier-down' closed
check "старший закрыт — читается открытый, что ниже номером" \
  "$MAIL/077-notifier-down/messages" "$(notifier_mute_source "$MAIL" 'notifier-down')"

receiver '077-notifier-down' closed
check "все приёмники закрыты — ленты нет, звонок не глушится" \
  "" "$(notifier_mute_source "$MAIL" 'notifier-down')"

# Чужой адрес соседним слагом не отвечает: слаг — это и есть имя адреса.
receiver '076-main-red-alarm' open
check "слаг различает адреса" \
  "" "$(notifier_mute_source "$MAIL" 'notifier-down')"
check "слаг соседнего адреса отдаёт свою ленту" \
  "$MAIL/076-main-red-alarm/messages" "$(notifier_mute_source "$MAIL" 'main-red-alarm')"

# Тред без `_meta.md` не кандидат — по той же причине, по которой его пропускает
# дверь: ленту, которую некому прочитать, судить нечем.
mkdir -p "$MAIL/091-notifier-down/messages"
check "приёмник без _meta.md пропускается" \
  "" "$(notifier_mute_source "$MAIL" 'notifier-down')"

# 9. СТЫК ДВУХ ПРАВИЛ: лента выбранного приёмника — это то, по чему решает
#    глушение. Проверяется вместе, потому что порознь обе половины зелены и в
#    том случае, когда воркфлоу читает не тот тред.
receiver '108-notifier-down' open
{
  printf '🔕 **Уведомитель `%s` отказал: `failure`.**\n\n' 'Comms Derived'
  printf '%s · окно %s с\n' "$(notifier_mute_marker 'Comms Derived')" "$NOTIFIER_MUTE_WINDOW_SEC"
} > "$MAIL/108-notifier-down/messages/2026-09-03T16-39-00Z-github.md"
check "решение принимается по ленте выбранного приёмника" \
  "mute 2026-09-03T16:39:00Z 30" \
  "$(notifier_mute_decide "$(notifier_mute_source "$MAIL" 'notifier-down')" 'Comms Derived' '2026-09-03T16:39:30Z')"
# --- 10. ПРЕДИКАТ ГРОМКОСТИ: какие прогоны заглушены (тред 119) ---------------
#
# Первоисточник: письмо смотрителя от 2026-09-03T17:59:23Z (прогон 33787757989)
# напечатало «НЕ ПРОЧИТАНО: GitHub API отказал», а в его же логе стояло
# `expected an object but got: array` — фильтр был тип-ошибочен ПРИ ЛЮБЫХ
# данных, то есть ветвь счёта не могла дать число никогда. Живого отказа для
# проверки не нужно: предикат кормится сохранённым ответом API.
RUNS_JSON="$DIR/runs.json"
cat > "$RUNS_JSON" <<'JSON'
{ "total_count": 11,
  "workflow_runs": [
    { "id": 33787502420, "created_at": "2026-09-03T17:59:00Z", "conclusion": "failure" },
    { "id": 33787757989, "created_at": "2026-09-03T17:59:23Z", "conclusion": "failure" },
    { "id": 33780000001, "created_at": "2026-09-03T15:00:00Z", "conclusion": "success" },
    { "id": 33780000002, "created_at": "2026-09-03T14:00:00Z", "conclusion": "timed_out" },
    { "id": 33770000003, "created_at": "2026-09-03T12:00:00Z", "conclusion": "failure" },
    { "id": 33780000004, "created_at": "2026-09-03T16:00:00Z", "conclusion": "cancelled" },
    { "id": 33780000005, "created_at": "2026-09-03T16:05:00Z", "conclusion": "skipped" },
    { "id": 33780000006, "created_at": "2026-09-03T16:10:00Z", "conclusion": null },
    { "id": 33780000007, "created_at": "2026-09-03T16:15:00Z", "conclusion": "startup_failure" },
    { "id": 33780000008, "created_at": "2026-09-03T16:20:00Z", "conclusion": "action_required" },
    { "id": 33780000009, "created_at": "2026-09-03T16:25:00Z", "conclusion": "stale" }
  ] }
JSON

# (а) отказные позже прошлого письма — их id, и (г) смесь заключений отбирается
#     правильно и НЕ РОНЯЕТ фильтр: `success`, `cancelled`, `skipped` и `null`
#     молча отсеиваются, а не дают тип-ошибку.
check "отказные позже прошлого письма — их id, смесь заключений не роняет фильтр" \
  "33787502420 33780000002 33780000007 33780000008 33780000009" \
  "$(notifier_mute_muted_ids "$RUNS_JSON" '2026-09-03T13:39:47Z' 33787757989 "")"
# (в) СВОЙ прогон в выдачу не попадает: он создан позже прошлого письма и
#     завершится отказом, но письмо о нём как раз и едет — заглушённым он не был.
check "свой прогон в выдачу не попадает" "нет" \
  "$(out_probe notifier_mute_muted_ids "$RUNS_JSON" '2026-09-03T13:39:47Z' 33787757989 "" -- -F 33787757989)"
check "прогон старше прошлого письма не считается заглушённым" "нет" \
  "$(out_probe notifier_mute_muted_ids "$RUNS_JSON" '2026-09-03T13:39:47Z' 33787757989 "" -- -F 33770000003)"
# (б) отказных нет — ПУСТОЙ список и код 0, а не отказ: «заглушать было нечего»
#     это исход, а не ошибка.
check "отказных нет — пустой список" "" \
  "$(notifier_mute_muted_ids "$RUNS_JSON" '2026-09-03T18:00:00Z' 33787757989 "")"
check "отказных нет — код 0, а не отказ" "0" \
  "$(notifier_mute_muted_ids "$RUNS_JSON" '2026-09-03T18:00:00Z' 33787757989 "" >/dev/null; echo $?)"
check "все отказные — это свой прогон и старьё, ответ пуст" "" \
  "$(notifier_mute_muted_ids "$RUNS_JSON" '2026-09-03T17:30:00Z' 33787502420 "" | sed 's/33787757989//;s/^ *//;s/ *$//')"
# Мусор вместо ответа — отказ предиката, и ветвь обязана его увидеть кодом.
printf 'не json\n' > "$DIR/broken.json"
# КОД НАЗЫВАЕТСЯ ЧИСЛОМ, А НЕ СВОДИТСЯ К «нет»: прежняя форма зеленела и от отсутствия
# самой функции, и от отказа совсем другого разбора внутри неё.
check "ответ не разобрался — отказ разбора (код 5), а не любой ненулевой" "код 5" \
  "$(rc_probe notifier_mute_muted_ids "$DIR/broken.json" '2026-09-03T13:39:47Z' 1 "")"
# И ОТКАЗ ЧТЕНИЯ — ДРУГОЙ КОД, а не тот же самый: файла нет — это не «json не разобрался».
check "файла ответа нет вовсе — это ДРУГОЙ отказ (код 2)" "код 2" \
  "$(rc_probe notifier_mute_muted_ids "$DIR/нет-такого.json" '2026-09-03T13:39:47Z' 1 "")"

# --- 10а. ВРЕМЯ ОДНОГО ЗАГЛУШЁННОГО ПРОГОНА (тред 198, случай 3) --------------
#
# Первоисточник: письмо 2026-09-13T16:28:49Z, хвост «прогоны 34759515483,
# 34759487215» — оба из ПРОШЛОЙ аварии, старший старше границы текущей на
# 3 ч 13 мин 03 с, а времени у номеров не напечатано ни у одного. Предикат
# отдаёт время ровно из того ответа API, которым отобран сам номер: своего
# отбора у него нет, и разъехаться со счётом ему нечем.
check "время прогона берётся из ответа" "2026-09-03T14:00:00Z" \
  "$(notifier_mute_muted_at "$RUNS_JSON" 33780000002)"
check "и у прогона из другой части выдачи — своё" "2026-09-03T17:59:00Z" \
  "$(notifier_mute_muted_at "$RUNS_JSON" 33787502420)"
# ПРОГОНА НЕТ В ОТВЕТЕ — ОТКАЗ ПО ИМЕНИ, а не пустая строка: пустая напечаталась
# бы голым числом, то есть вернула бы чинимый дефект в тот единственный случай,
# когда его никто не ждёт.
check "прогона в ответе нет — отказ (код 5), а не пустая строка" "код 5" \
  "$(rc_probe notifier_mute_muted_at "$RUNS_JSON" 99999999999)"
check "мусор вместо ответа — отказ разбора (код 5)" "код 5" \
  "$(rc_probe notifier_mute_muted_at "$DIR/broken.json" 33780000002)"
check "файла ответа нет вовсе — ДРУГОЙ отказ (код 2)" "код 2" \
  "$(rc_probe notifier_mute_muted_at "$DIR/нет-такого.json" 33780000002)"

# --- 10в. МГНОВЕНИЕ ОТБОРА — ЗАВЕРШЕНИЕ, А НЕ СТАРТ (тред 209) ----------------
#
# ПОЛЕВОЙ СЛУЧАЙ, РАЗЫГРАННЫЙ ДОСЛОВНО (2026-09-14, стоячий адрес
# `209-notifier-down`). Письмо уехало 15:52:09Z, следующее — 16:13Z. В окне
# отказали ДВА круга `Claude PR Review`, и письмо назвало ОДИН: у прогона
# `34864294084` старт (15:45:51Z) лежит РАНЬШЕ прошлого письма, а отказ
# (15:53:05Z) — позже. Судя по старту, перепись его роняла молча — то есть число,
# которым письмо отчитывается о съеденном глушением, занижалось.
#
# Фикстура отдана в том порядке, в каком её отдаёт API: новейший по `created`
# первым. Третий прогон (`34863000001`) — контроль: он и завёлся, и отказал ДО
# прошлого письма, и заглушённым не является ни по одному из двух правил.
INFLIGHT_JSON="$DIR/inflight.json"
cat > "$INFLIGHT_JSON" <<'JSON'
{ "total_count": 4,
  "workflow_runs": [
    { "id": 34866710091, "created_at": "2026-09-14T16:08:20Z", "updated_at": "2026-09-14T16:13:24Z", "conclusion": "failure" },
    { "id": 34865984206, "created_at": "2026-09-14T16:01:36Z", "updated_at": "2026-09-14T16:06:05Z", "conclusion": "failure" },
    { "id": 34864294084, "created_at": "2026-09-14T15:45:51Z", "updated_at": "2026-09-14T15:53:05Z", "conclusion": "failure" },
    { "id": 34863000001, "created_at": "2026-09-14T15:40:00Z", "updated_at": "2026-09-14T15:50:00Z", "conclusion": "failure" }
  ] }
JSON
# ПРЕДМЕТ ЗДЕСЬ ПУСТОЙ, И ЭТО НЕ НЕБРЕЖНОСТЬ (тред 198): у прогонов фикстуры нет
# ни номера PR, ни события `pull_request`, то есть ладдер разрешает их предмет в
# пустую строку — ключом служит голое имя уведомителя. Мгновение отбора и предмет
# — две независимые оси, и эта фикстура держит первую, не примешивая вторую.
#
# Эта сверка и есть весь тред: судя по старту, ответ был бы «34865984206».
check "прогон, начавшийся ДО письма и отказавший ПОСЛЕ, из переписи не выпадает" \
  "34865984206 34864294084" \
  "$(notifier_mute_muted_ids "$INFLIGHT_JSON" '2026-09-14T15:52:09Z' 34866710091 "")"
check "а отказавший ДО письма заглушённым по-прежнему не считается" "нет" \
  "$(out_probe notifier_mute_muted_ids "$INFLIGHT_JSON" '2026-09-14T15:52:09Z' 34866710091 "" -- -F 34863000001)"
# ЗАПАСНОЙ ХОД `// .created_at` ПРОВЕРЯЕТСЯ ТЕМ, ЧТО ФИКСТУРА ВЫШЕ ЕГО НЕ ИМЕЕТ:
# в `$RUNS_JSON` поля `updated_at` нет ни у одного прогона, и раздел 10 целиком
# судит по старту — то есть в точности прежним правилом. Здесь это называется
# сверкой, а не оставляется совпадением.
check "без поля updated_at отбор судит по старту, а не пропускает прогон" \
  "33787502420 33780000002 33780000007 33780000008 33780000009" \
  "$(notifier_mute_muted_ids "$RUNS_JSON" '2026-09-03T13:39:47Z' 33787757989 "")"

# ВТОРАЯ ПЕРЕПИСЬ ТОЙ ЖЕ ВЫДАЧИ СУДИТ ТЕМ ЖЕ МГНОВЕНИЕМ (тред 209 против 198).
# `notifier_mute_ambiguous` печатается в ТУ ЖЕ строку письма, что и число: она
# говорит, почему число объявлено нижней границей. Разъехавшись с числом мгновением
# отбора, она превращает «НЕ МЕНЕЕ N» в «ровно N» — прогон, заведённый ДО письма и
# отказавший ПОСЛЕ, не попадает ни в число (предмет не разрешён), ни в причину.
# Фикстура — тот же полевой случай, только предметы разрешаются в голову: наш ключ
# предметный (`#443`), у кандидата номера в выдаче нет, значит он НЕРАЗЛИЧИМ.
AMBIG_INFLIGHT_JSON="$DIR/inflight-ambiguous.json"
cat > "$AMBIG_INFLIGHT_JSON" <<'JSON'
{ "total_count": 2,
  "workflow_runs": [
    { "id": 34866710091, "created_at": "2026-09-14T16:08:20Z", "updated_at": "2026-09-14T16:13:24Z", "conclusion": "failure", "event": "pull_request", "head_sha": "afa6ad76", "pull_requests": [] },
    { "id": 34864294084, "created_at": "2026-09-14T15:45:51Z", "updated_at": "2026-09-14T15:53:05Z", "conclusion": "failure", "event": "pull_request", "head_sha": "c32b6ee4", "pull_requests": [] }
  ] }
JSON
check "неразличимый прогон, отказавший ПОСЛЕ письма, из причины не выпадает" "1" \
  "$(notifier_mute_ambiguous "$AMBIG_INFLIGHT_JSON" '2026-09-14T15:52:09Z' 34866710091 '#443')"
# ЗАПАСНОЙ ХОД `// .created_at` У ЭТОЙ ПЕРЕПИСИ ПРОВЕРЕН НЕ ЗДЕСЬ, А РАЗДЕЛОМ
# ПРЕДМЕТА: фикстура `$SUBJ_JSON` поля `updated_at` не имеет ни у одного прогона,
# и сверка «прогон с неразрешённым предметом назван, а не проглочен» судит её по
# старту. Вторую копию того же случая здесь не заводим — она пиньила бы саму себя.

# --- 10г. МЕТКА ЗАПРОСА: прошлое письмо МИНУС слак полёта (тред 209) ----------
#
# Правильный предикат судить может только то, что приехало, а сузить выдачу API
# умеет лишь по `created`. Поэтому у запроса своя метка — шире метки письма ровно
# на то время, которое прогон может лететь.
check "метка запроса — прошлое письмо минус слак" "2026-09-14T14:52:09Z" \
  "$(notifier_mute_census_since '2026-09-14T15:52:09Z' 3600)"
check "слак по умолчанию — час, и он тот же" "2026-09-14T14:52:09Z" \
  "$(notifier_mute_census_since '2026-09-14T15:52:09Z')"
# НЕРАЗОБРАННАЯ ДАТА НЕ РАСШИРЯЕТ И НЕ РОНЯЕТ: письмо о красноте важнее полноты
# хвоста, поэтому метка отдаётся как есть — это прежнее поведение, а не отказ.
check "метку, которую date не понял, перепись не расширяет" "имя-не-дата" \
  "$(notifier_mute_census_since 'имя-не-дата')"
check "и это не отказ — код 0" "0" \
  "$(notifier_mute_census_since 'имя-не-дата' >/dev/null; echo $?)"
# Слак не-числом не роняет арифметику и не даёт случайный интервал.
check "слак не-числом откатывается к умолчанию, а не ломает счёт" "2026-09-14T14:52:09Z" \
  "$(notifier_mute_census_since '2026-09-14T15:52:09Z' 'полчаса')"
# И МУСОР В САМОМ УМОЛЧАНИИ ТОЖЕ: переменная приходит из окружения шага, а
# упавшая на ней арифметика оставила бы письмо о красноте неотправленным.
check "мусор в переменной окружения не роняет счёт" "2026-09-14T14:52:09Z" \
  "$(NOTIFIER_MUTE_INFLIGHT_SEC='час' notifier_mute_census_since '2026-09-14T15:52:09Z')"

# --- 10д. СТЫК 209 × 198: ВРЕМЯ В ХВОСТЕ — ТО ЖЕ МГНОВЕНИЕ, ЧТО И ОТБОР -------
#
# Два треда сошлись на одном прогоне, и по отдельности каждый прав. Тред 209
# сделал мгновением отбора ЗАВЕРШЕНИЕ (`updated_at // .created_at`), тред 198
# печатает время у каждого номера хвоста. Возьми `muted_at` время из другого
# поля — и письмо назовёт заглушённым прогон, чьё напечатанное время лежит
# РАНЬШЕ прошлого письма, названного в той же строке. Читатель, ради которого
# время и печатается, прочёл бы это как «хвост врёт», и был бы прав по тексту.
#
# ЭТО НЕ ГИПОТЕЗА, А ТОТ ЖЕ ПОЛЕВОЙ ПРОГОН: `34864294084` заведён 15:45:51Z,
# отказал 15:53:05Z, прошлое письмо 15:52:09Z. По старту его время старше
# письма на 6 мин 18 с; по завершению — моложе на 56 с, и именно завершение
# ввело его в перепись.
check "у прогона, отобранного по завершению, печатается завершение" "2026-09-14T15:53:05Z" \
  "$(notifier_mute_muted_at "$INFLIGHT_JSON" 34864294084)"
# ЗАПАСНОЙ ХОД ТОТ ЖЕ, ЧТО У ОТБОРА, и проверяется тем же способом: в
# `$RUNS_JSON` поля `updated_at` нет, и раздел 10а целиком судит по старту.
check "без поля updated_at время берётся из старта, а не отказывает" "2026-09-03T14:00:00Z" \
  "$(notifier_mute_muted_at "$RUNS_JSON" 33780000002)"
# И НАЗВАННОЕ ВРЕМЯ ПРАВДА ПОЗЖЕ ПРОШЛОГО ПИСЬМА — сверка отношения, а не
# литерала: она красна при ЛЮБОМ возврате к старту, включая будущие правки.
check "время каждого номера хвоста позже прошлого письма" "да" \
  "$(_last='2026-09-14T15:52:09Z'; _ok=да
     for _id in $(notifier_mute_muted_ids "$INFLIGHT_JSON" "$_last" 34866710091 ""); do
       _at="$(notifier_mute_muted_at "$INFLIGHT_JSON" "$_id")"
       [ "$_at" \> "$_last" ] || _ok="нет ($_id: $_at)"
     done; printf '%s' "$_ok")"

# --- 10б. ПРЕДИКАТ ПОЛНОТЫ ВЫБОРКИ: сколько под запрос попало, но не влезло ----
#
# Первоисточник (тред 126): страница берётся одна, и у `Comms Derived` сотня
# новейших прогонов накрывает ~15 часов при 2060 всего — то есть число заглушённых
# занижалось МОЛЧА, стоило письмам разойтись на сутки. Предикат по файлу об этом
# знать не мог: ему отдают ответ, а не запрос. Признак обрыва — `total_count`
# против длины страницы.
#
# СТРАНИЦА РОВНО НА ГРАНИЦЕ: самый старый прогон выборки создан ровно в метку
# прошлого письма. Выборка не оборвалась (`total_count` = длине), и сам
# пограничный прогон заглушённым не считается — `created > $last_at` строгое, и
# `created=>` в запросе к API тоже (проверено на бою 2026-09-04: запрос с меткой
# новейшего прогона отдал total_count 0).
BOUNDARY_JSON="$DIR/boundary.json"
cat > "$BOUNDARY_JSON" <<'JSON'
{ "total_count": 3,
  "workflow_runs": [
    { "id": 41000000003, "created_at": "2026-09-04T10:00:00Z", "conclusion": "failure" },
    { "id": 41000000002, "created_at": "2026-09-04T09:00:00Z", "conclusion": "failure" },
    { "id": 41000000001, "created_at": "2026-09-04T08:00:00Z", "conclusion": "failure" }
  ] }
JSON
check "страница ровно на границе — выборка полна" "0" \
  "$(notifier_mute_page_shortfall "$BOUNDARY_JSON")"
check "и пограничный прогон заглушённым не считается" "41000000003 41000000002" \
  "$(notifier_mute_muted_ids "$BOUNDARY_JSON" '2026-09-04T08:00:00Z' 0 "")"

# СТРАНИЦА, УПЁРШАЯСЯ В КРАЙ: под запрос попало больше, чем отдали. Число
# непоместившихся называется, а не выводится читателем из разницы.
TRUNCATED_JSON="$DIR/truncated.json"
cat > "$TRUNCATED_JSON" <<'JSON'
{ "total_count": 321,
  "workflow_runs": [
    { "id": 42000000002, "created_at": "2026-09-04T10:00:00Z", "conclusion": "failure" },
    { "id": 42000000001, "created_at": "2026-09-04T09:00:00Z", "conclusion": "success" }
  ] }
JSON
check "страница упёрлась в край — названо, сколько не влезло" "319" \
  "$(notifier_mute_page_shortfall "$TRUNCATED_JSON")"

# ПУСТАЯ СТРАНИЦА — это полная выборка, а не обрыв: с прошлого письма прогонов
# не было вовсе. Считать её оборванной значило бы объявлять нижнюю границу там,
# где число точно и равно нулю.
EMPTY_JSON="$DIR/empty.json"
printf '{ "total_count": 0, "workflow_runs": [] }\n' > "$EMPTY_JSON"
check "пустая страница — выборка полна, а не оборвана" "0" \
  "$(notifier_mute_page_shortfall "$EMPTY_JSON")"
check "и заглушённых в ней нет" "" \
  "$(notifier_mute_muted_ids "$EMPTY_JSON" '2026-09-04T08:00:00Z' 0 "")"

# ОТСУТСТВИЕ `total_count` — ОТКАЗ ПО ИМЕНИ, А НЕ МОЛЧАЛИВЫЙ НОЛЬ: ноль здесь
# читался бы как «число полное», то есть был бы ровно той ложью, ради которой
# предикат и написан.
printf '{ "workflow_runs": [] }\n' > "$DIR/no-total.json"
check "нет total_count — отказ счёта (код 5), а не ноль" "код 5" \
  "$(rc_probe notifier_mute_page_shortfall "$DIR/no-total.json")"
printf '{ "total_count": 5 }\n' > "$DIR/no-runs.json"
check "нет workflow_runs — отказ счёта (код 5)" "код 5" \
  "$(rc_probe notifier_mute_page_shortfall "$DIR/no-runs.json")"
check "мусор вместо ответа — отказ счёта (код 5)" "код 5" \
  "$(rc_probe notifier_mute_page_shortfall "$DIR/broken.json")"
check "файла ответа нет вовсе — ДРУГОЙ отказ (код 2)" "код 2" \
  "$(rc_probe notifier_mute_page_shortfall "$DIR/нет-такого.json")"

# --- 11. ТРИ ИСХОДА ВЕТВИ ГРОМКОСТИ — сверяется ТЕКСТ, а не код выхода --------
#
# Дефект треда 119 был ТЕКСТОВЫМ: достижимой оставалась одна ветвь из трёх, и
# она называла виноватым GitHub. Поэтому проверяется строка, которую читатель
# треда увидит. Тело вырезается из `notifier-watch.yml` по маркерам — судится
# файл, который едет, а не его пересказ; формулировки обязаны жить в `.yml`
# (см. комментарий там: `.github/scripts/**` не покрыт `powerDocuments`).
WATCH_YML=../workflows/notifier-watch.yml
BLOCK="$DIR/muted-line.sh"
sed -n '/# >>> notifier-mute: громкость >>>/,/# <<< notifier-mute: громкость <<</p' "$WATCH_YML" \
  | sed '1d;$d' | sed 's/^          //' > "$BLOCK"
# ДВЕ ПРОБЫ, А НЕ ОДНА СЦЕПКА: `A && B && echo да || echo нет` не говорит, какая из двух
# половин не нашлась, и отвечает тем же `нет`, когда `$BLOCK` не создался вовсе (код 2).
check "тело ветви вырезано из notifier-watch.yml: строка MUTED_LINE на месте" "да" \
  "$(file_probe -F 'MUTED_LINE=' "$BLOCK")"
check "тело ветви вырезано из notifier-watch.yml: предикат громкости на месте" "да" \
  "$(file_probe -F 'notifier_mute_muted_ids' "$BLOCK")"
check "тело ветви вырезано из notifier-watch.yml: метка запроса считается функцией" "да" \
  "$(file_probe -F 'notifier_mute_census_since' "$BLOCK")"

GH_ARGS="$DIR/gh.args"
muted_line() { # <ok|fail — исход gh> <файл-ответ> <LAST_AT> <RUN_ID> [<предмет>]
  (
    set -euo pipefail
    GH_OUTCOME="$1"
    GH_BODY="$2"
    LAST_AT="$3"
    RUN_ID="$4"
    # Предмет и ключ — то, чем ветвь громкости теперь и считает (тред 198).
    SUBJECT="${5-}"
    MUTE_KEY="$(notifier_mute_key 'Claude PR Review' "$SUBJECT")"
    # Окружение шага — подложное: харнесс задаёт его сам, поэтому имена
    # переменных `env:` воркфлоу сверяются отдельно (раздел 12 ниже).
    GITHUB_REPOSITORY='lle/agent-crew-orchestrator'
    GITHUB_SERVER_URL='https://github.com'
    GITHUB_RUN_ID=33787757989
    WF_NAME='Claude PR Review'
    WF_ID=178000000
    # Запрос записывается: интервал выборки — часть починки треда 126, и
    # проверять его надо по тому, что ветвь спросила у GitHub, а не по тому, что
    # ей подложили в ответ.
    gh() { printf '%s\n' "$*" > "$GH_ARGS"; [ "$GH_OUTCOME" = ok ] || return 1; cat "$GH_BODY"; }
    # shellcheck source=/dev/null
    source "$BLOCK"
    printf '%s' "$MUTED_LINE"
  )
}

check "исход 1 — число со списком прогонов" \
  '🔇 **Заглушено с прошлого письма (`2026-09-03T13:39:47Z`) отказов с тем же ключом `Claude PR Review`: 5** — прогоны 33787502420 (2026-09-03T17:59:00Z), 33780000002 (2026-09-03T14:00:00Z), 33780000007 (2026-09-03T16:15:00Z), 33780000008 (2026-09-03T16:20:00Z), 33780000009 (2026-09-03T16:25:00Z). У каждого прогона названо его собственное время: хвост считается с прошлого письма, а не с начала этой аварии, и относиться к ней не обязан. Правило — окно 900 с по ключу «имя уведомителя + предмет прогона» (`.github/scripts/notifier-mute.sh`).' \
  "$(muted_line ok "$RUNS_JSON" '2026-09-03T13:39:47Z' 33787757989)"
check "исход 2 — заглушать было нечего" \
  '🔇 С прошлого письма (`2026-09-03T18:00:00Z`) других отказов с ключом `Claude PR Review` не было — заглушать было нечего.' \
  "$(muted_line ok "$RUNS_JSON" '2026-09-03T18:00:00Z' 33787757989)"
# ИСХОД 3, СТОРОНА ЗАПРОСА: GitHub тут действительно ни при чём как ПРИЧИНА,
# названная наугад, — назван отказ запроса, и читатель послан в лог смотрителя.
check "исход 3а — запрос не выполнен, и это сказано отдельно от разбора" \
  '🔇 Сколько отказов с ключом `Claude PR Review` заглушено с прошлого письма (`2026-09-03T13:39:47Z`) — НЕ ПРОЧИТАНО: список прогонов не получен — запрос к GitHub не выполнен. Само письмо это не задержало. Настоящая ошибка напечатана в логе ЭТОГО прогона смотрителя — https://github.com/lle/agent-crew-orchestrator/actions/runs/33787757989, шаг «Позвонить в тред-приёмник»; в прогонах `Claude PR Review` её нет.' \
  "$(muted_line fail "$RUNS_JSON" '2026-09-03T13:39:47Z' 33787757989)"
# ИСХОД 3б — РОВНО ТОТ ЖИВОЙ СЛУЧАЙ: запрос прошёл, сломан разбор. Прежняя ветвь
# печатала здесь «GitHub API отказал» и посылала читателя в исправную сторону.
BRANCH_ERR="$DIR/branch.err"
check "исход 3б — ответ получен, но не разобран: виноватым GitHub не назван" \
  '🔇 Сколько отказов с ключом `Claude PR Review` заглушено с прошлого письма (`2026-09-03T13:39:47Z`) — НЕ ПРОЧИТАНО: список прогонов получен, но не разобран — отказал отбор отказных прогонов. Само письмо это не задержало. Настоящая ошибка напечатана в логе ЭТОГО прогона смотрителя — https://github.com/lle/agent-crew-orchestrator/actions/runs/33787757989, шаг «Позвонить в тред-приёмник»; в прогонах `Claude PR Review` её нет.' \
  "$(muted_line ok "$DIR/broken.json" '2026-09-03T13:39:47Z' 33787757989 2>"$BRANCH_ERR")"
# Обещание строки проверяется, а не декларируется: раз письмо посылает читателя
# в лог прогона смотрителя, ошибка обязана там БЫТЬ. Именно она и уехала бы в
# `/dev/null`, останься фильтр внутри `gh --jq`.
# ТРИ ИСХОДА И ЗДЕСЬ: `[ -s … ]` отвечает `нет` и когда ветвь смолчала, и когда файла нет
# вовсе — то есть когда сверка не состоялась, а харнесс до неё не доехал.
check "и настоящая ошибка правда напечатана в лог прогона" "да" \
  "$(if [ ! -e "$BRANCH_ERR" ]; then echo "проба не состоялась (файла stderr ветви нет)"; \
     elif [ -s "$BRANCH_ERR" ]; then echo да; else echo нет; fi)"
check "прошлого письма нет — строки громкости нет вовсе" "" \
  "$(muted_line ok "$RUNS_JSON" - 33787757989)"

# ИСХОД 3в (тред 126) — ответ получен и разобран, а полнота выборки нет. Это
# третий подслучай «не прочитано», и он назван своим именем: молчаливый ноль
# непоместившихся означал бы «число полное», то есть то самое враньё числом.
check "исход 3в — полнота выборки не сосчитана, и это сказано отдельно" \
  '🔇 Сколько отказов с ключом `Claude PR Review` заглушено с прошлого письма (`2026-09-04T08:00:00Z`) — НЕ ПРОЧИТАНО: список прогонов получен и разобран, но полнота выборки не сосчитана — отказал счёт непоместившихся прогонов. Само письмо это не задержало. Настоящая ошибка напечатана в логе ЭТОГО прогона смотрителя — https://github.com/lle/agent-crew-orchestrator/actions/runs/33787757989, шаг «Позвонить в тред-приёмник»; в прогонах `Claude PR Review` её нет.' \
  "$(muted_line ok "$DIR/no-total.json" '2026-09-04T08:00:00Z' 33787757989 2>/dev/null)"

# --- 11б. ЧЕТВЁРТЫЙ ИСХОД: ЧИСЛО НАЗВАНО НИЖНЕЙ ГРАНИЦЕЙ (тред 126) -----------
#
# Ровно тот случай, ради которого заведён тред: под запрос попало больше, чем
# страница отдала. Прежняя ветвь напечатала бы меньшее число как точное, и
# отличить его от правды читателю было бы нечем. Теперь строка говорит «НЕ МЕНЕЕ
# N» и называет, сколько прогонов в выборку не поместилось.
check "исход 4 — обрыв выборки: число объявлено нижней границей" \
  '🔇 **Заглушено с прошлого письма (`2026-09-04T08:00:00Z`) отказов с тем же ключом `Claude PR Review`: НЕ МЕНЕЕ 1** — прогоны 42000000002 (2026-09-04T10:00:00Z). У каждого прогона названо его собственное время: хвост считается с прошлого письма, а не с начала этой аварии, и относиться к ней не обязан. Это НИЖНЯЯ ГРАНИЦА, а не число: за один запрос GitHub отдаёт 100 новейших прогонов, а под запрос переписи у `Claude PR Review` их попало больше — 319 в выборку не поместились, и отказы среди них не сосчитаны. Правило — окно 900 с по ключу «имя уведомителя + предмет прогона» (`.github/scripts/notifier-mute.sh`).' \
  "$(muted_line ok "$TRUNCATED_JSON" '2026-09-04T08:00:00Z' 33787757989)"
# Ноль отказов на ОБОРВАННОЙ выборке — это НЕ «заглушать было нечего»: нечего
# заглушать могло и не быть, а могло и быть за краем страницы. Список прогонов
# при этом не печатается пустым хвостом.
check "исход 4 при нуле найденных — не «нечего», а нижняя граница 0" \
  '🔇 **Заглушено с прошлого письма (`2026-09-04T11:00:00Z`) отказов с тем же ключом `Claude PR Review`: НЕ МЕНЕЕ 0**. Это НИЖНЯЯ ГРАНИЦА, а не число: за один запрос GitHub отдаёт 100 новейших прогонов, а под запрос переписи у `Claude PR Review` их попало больше — 319 в выборку не поместились, и отказы среди них не сосчитаны. Правило — окно 900 с по ключу «имя уведомителя + предмет прогона» (`.github/scripts/notifier-mute.sh`).' \
  "$(muted_line ok "$TRUNCATED_JSON" '2026-09-04T11:00:00Z' 33787757989)"
check "полная выборка нижней границей не прикрывается" "нет" \
  "$(out_probe muted_line ok "$RUNS_JSON" '2026-09-03T13:39:47Z' 33787757989 -- -F 'НЕ МЕНЕЕ')"

# --- 11в. ИНТЕРВАЛ СТОИТ В ЗАПРОСЕ, А НЕ ТОЛЬКО В ФИЛЬТРЕ (тред 126) ----------
#
# Половина починки — в том, ЧТО спрошено: страница тратится на сто новейших
# прогонов ИЗ ИНТЕРВАЛА, а не на сто новейших вообще. Проверяется по записанному
# вызову `gh`, потому что по ответу этого не видно: подложить можно любой.
muted_line ok "$RUNS_JSON" '2026-09-03T13:39:47Z' 33787757989 >/dev/null
# МЕТКА ЗАПРОСА ШИРЕ МЕТКИ ПИСЬМА НА СЛАК ПОЛЁТА (тред 209): спросить ровно с
# прошлого письма значит не получить прогон, который в тот момент ещё летел, —
# а именно он и оказывается заглушённым.
check "запрос ограничен интервалом, начатым слаком раньше прошлого письма" "да" \
  "$(file_probe -F 'created=%3E2026-09-03T12:39:47Z' "$GH_ARGS")"
# И ЭТО НЕ «СПРОСИТЬ ВСЁ»: интервал остаётся интервалом, иначе починка треда 126
# (страница тратится на новейшие вообще) вернулась бы этой же правкой.
check "интервал не снят вовсе — метка в запросе есть" "да" \
  "$(file_probe -F 'created=%3E' "$GH_ARGS")"
# А ЧИТАТЕЛЮ ПО-ПРЕЖНЕМУ НАЗЫВАЕТСЯ МЕТКА ПИСЬМА, а не метка запроса: глушение
# считается от письма, шире только выборка, и путать их в отчёте нельзя.
check "в тексте письма стоит метка ПИСЬМА, а не расширенная метка запроса" "нет" \
  "$(out_probe muted_line ok "$RUNS_JSON" '2026-09-03T13:39:47Z' 33787757989 -- -F '2026-09-03T12:39:47Z')"
# `! grep …` в прежней сцепке был опаснее прочего: отрицание превращает код 2 (файла нет,
# битый шаблон) в ИСТИНУ, то есть несостоявшаяся половина пробы читалась как «пройдено».
check "и это одна страница: размер страницы задан" "да" \
  "$(file_probe -F 'per_page=100' "$GH_ARGS")"
check 'и это не обход всех — `--paginate` в запросе нет' "нет" \
  "$(file_probe -F -- '--paginate' "$GH_ARGS")"

# --- 12. Переменные окружения ветви объявлены шагом ---------------------------
#
# Подложное окружение раздела 11 задаёт харнесс, а не воркфлоу: опечатка в `env:`
# шага так не ловится. Поэтому имена, которые тело берёт снаружи, сверяются с
# файлом отдельно. `GITHUB_*` даёт Actions сам и в `env:` их не объявляют.
# `WF_PR`/`WF_EVENT`/`HEAD_SHA` — вход ладдера предмета (тред 198): без них ключ
# молча падает на имя, то есть возвращается сегодняшний дефект.
for VAR in WF_NAME WF_ID RUN_ID WF_PR WF_EVENT HEAD_SHA; do
  check "ветвь берёт ${VAR}, и шаг его объявляет" "да" \
    "$(file_probe -e "^          ${VAR}: " "$WATCH_YML")"
done

# --- 13. СТЫК АДРЕСА И ГРОМКОСТИ: метку даёт лента приёмника (тред 080), по ---
#     ней считает ветвь громкости (тред 119)
#
# Две правки сошлись в одном шаге, и порознь обе половины зелены даже когда они
# спорят: выбор приёмника КОНЧАЕТСЯ меткой прошлого письма `LAST_AT`, а ветвь
# громкости с неё НАЧИНАЕТСЯ. Поэтому здесь они гоняются подряд, как в шаге:
# лента текущего приёмника → метка → строка, которую увидит читатель треда.
# Почта `$MAIL` — та же, что в разделе 9: открыт один приёмник `108`, у него
# письмо об отказе `Comms Derived` от 2026-09-03T16:39:00Z.
last_at_of_address() { # <корень почты> <слаг адреса> <ISO сейчас>
  local src
  src="$(notifier_mute_source "$1" "$2")"
  # Открытого приёмника нет — шаг ставит `LAST_AT=-` (ветвь `deliver` в
  # `notifier-watch.yml`): письмо поедет и откроет приёмник, глушить нечего.
  if [ -z "$src" ]; then printf -- '-\n'; return 0; fi
  notifier_mute_decide "$src" 'Comms Derived' "$3" | cut -d' ' -f2
}

check "метка берётся у ленты ТЕКУЩЕГО приёмника адреса" "2026-09-03T16:39:00Z" \
  "$(last_at_of_address "$MAIL" 'notifier-down' '2026-09-03T18:00:00Z')"
check "и ветвь громкости считает по ней — числом, а не отказом чтения" \
  '🔇 **Заглушено с прошлого письма (`2026-09-03T16:39:00Z`) отказов с тем же ключом `Claude PR Review`: 1** — прогоны 33787502420 (2026-09-03T17:59:00Z). У каждого прогона названо его собственное время: хвост считается с прошлого письма, а не с начала этой аварии, и относиться к ней не обязан. Правило — окно 900 с по ключу «имя уведомителя + предмет прогона» (`.github/scripts/notifier-mute.sh`).' \
  "$(muted_line ok "$RUNS_JSON" "$(last_at_of_address "$MAIL" 'notifier-down' '2026-09-03T18:00:00Z')" 33787757989)"
# У адреса без открытого приёмника метки нет — и строки громкости нет: считать
# заглушённое против ленты, которой ещё не существует, значило бы соврать числом.
check "у адреса без открытого приёмника метки нет" "-" \
  "$(last_at_of_address "$MAIL" 'нет-такого-адреса' '2026-09-03T18:00:00Z')"
check "и строки громкости при этом нет вовсе" "" \
  "$(muted_line ok "$RUNS_JSON" "$(last_at_of_address "$MAIL" 'нет-такого-адреса' '2026-09-03T18:00:00Z')" 33787757989)"

# --- 14. КЛЮЧ ГЛУШЕНИЯ НЕСЁТ ПРЕДМЕТ (тред 198) ------------------------------
#
# Первоисточник: 2026-09-13 ключом было одно ИМЯ, и окно 900 с схлопнуло отказы
# кругов ревью по РАЗНЫМ PR в один звонок — отказ по #388 не прозвучал никогда.
# Проверяется ровно то, что этого стоило: два ключа в одном окне друг друга не
# глушат, один — глушит.

# (а) ЛАДДЕР ПРЕДМЕТА — читает ДАННЫЕ события, и ни одного имени воркфлоу в нём
#     нет. Три ветви, и каждая замерена полем 13.09 (номера прогонов — в шапке
#     `notifier-mute.sh`).
check "предмет: номер PR в событии — он и есть предмет" "#388" \
  "$(notifier_mute_subject pull_request 388 abc1234)"
check "предмет: номера нет, но событие pull_request — предмет есть по построению, берётся голова" \
  "@abc1234" "$(notifier_mute_subject pull_request '' abc1234)"
check "предмет: push — предмета нет по построению, ключ остаётся именем (защита петли 073)" \
  "" "$(notifier_mute_subject push '' abc1234)"
check "предмет: workflow_run без номера — тоже имя" \
  "" "$(notifier_mute_subject workflow_run '' abc1234)"

# (б) КЛЮЧ: пустой предмет даёт ГОЛОЕ ИМЯ, то есть поведение до треда 198 байт в
#     байт — это и есть доказательство, что `Comms Derived` не сдвинулся.
check "ключ без предмета — голое имя" "Comms Derived" \
  "$(notifier_mute_key 'Comms Derived' "$(notifier_mute_subject push '' abc1234)")"
check "ключ с предметом — имя плюс предмет" "Claude PR Review #388" \
  "$(notifier_mute_key 'Claude PR Review' "$(notifier_mute_subject pull_request 388 abc1234)")"

# (в) НЕСУЩЕЕ ТРЕБОВАНИЕ ПОСТАНОВКИ: ДВА КЛЮЧА В ОДНОМ ОКНЕ НЕ ГЛУШАТ ДРУГ
#     ДРУГА, ОДИН — ГЛУШИТ. Фикстура — тот самый живой случай: письмо про #409
#     лежит, отказ по #388 приходит через полминуты.
KEYS="$DIR/keys"
mkdir -p "$KEYS"
key_letter() { # <метка в имени файла> <ключ>
  {
    printf '🔕 **Уведомитель `Claude PR Review` отказал: `failure`.**\n\n'
    printf '%s · окно %s с\n' "$(notifier_mute_marker "$2")" "$NOTIFIER_MUTE_WINDOW_SEC"
  } > "$KEYS/$1-github.md"
}
key_letter '2026-09-13T13-58-00Z' 'Claude PR Review #409'
check "ДРУГОЙ предмет того же уведомителя в том же окне — письмо едет (дефект 198 закрыт)" \
  "deliver - -" "$(notifier_mute_decide "$KEYS" 'Claude PR Review #388' '2026-09-13T13:58:30Z')"
check "ТОТ ЖЕ предмет в том же окне — заглушён (глушение не потеряно)" \
  "mute 2026-09-13T13:58:00Z 30" "$(notifier_mute_decide "$KEYS" 'Claude PR Review #409' '2026-09-13T13:58:30Z')"
# И ключ-имя не глушится письмом о предмете того же уведомителя: `Claude PR
# Review` без предмета — это ДРУГОЙ ключ, а не «любой из них».
check "ключ-имя письмом о предмете не глушится" "deliver - -" \
  "$(notifier_mute_decide "$KEYS" 'Claude PR Review' '2026-09-13T13:58:30Z')"

# (г) КЛЮЧИ НЕПРЕФИКСНЫ — ровно тот класс, который стоил звонка, и держит его
#     закрывающая обратная кавычка маркера. `grep -lF` — поиск ПОДСТРОКИ, и без
#     неё `X` нашёл бы письмо про `X #388`, а `X #38` — тоже.
check "непрефиксность: короткий номер не находит письмо про длинный" "deliver - -" \
  "$(notifier_mute_decide "$KEYS" 'Claude PR Review #40' '2026-09-13T13:58:30Z')"
check "непрефиксность: длинный номер не находит письмо про короткий" "deliver - -" \
  "$(notifier_mute_decide "$KEYS" 'Claude PR Review #4099' '2026-09-13T13:58:30Z')"
# КОНТРОЛЬ МУТАЦИИ на самой кавычке: маркер без закрывающей кавычки — это и есть
# префиксный ключ, и он находит ЧУЖОЕ письмо. Проверяется грепом напрямую, чтобы
# сверка говорила про кавычку, а не про функцию.
check "мутация: маркер без закрывающей кавычки нашёл бы чужое письмо" "да" \
  "$(grep_probe "$(cat "$KEYS"/2026-09-13T13-58-00Z-github.md)" -F 'ключ глушения: `Claude PR Review')"
check "и с закрывающей кавычкой — не находит" "нет" \
  "$(grep_probe "$(cat "$KEYS"/2026-09-13T13-58-00Z-github.md)" -F 'ключ глушения: `Claude PR Review`')"

# --- 15. ЧЕСТНОСТЬ ЧИСЛА ПРИ ПРЕДМЕТНОМ КЛЮЧЕ (тред 198) ---------------------
#
# Как только ключ сузился, счёт обязан сузиться вместе с ним: письмо про `#388`,
# называющее числом отказы `#409`, — ложь в собственном отчёте, запрещённая
# шапкой `notifier-mute.sh`. И прогон, чей предмет не разрешился, не
# выбрасывается молча — он опускает число до нижней границы.
SUBJ_JSON="$DIR/subjects.json"
cat > "$SUBJ_JSON" <<'JSON'
{ "total_count": 5,
  "workflow_runs": [
    { "id": 51000000001, "created_at": "2026-09-13T14:00:00Z", "conclusion": "failure",
      "event": "pull_request", "head_sha": "aaa", "pull_requests": [ { "number": 388 } ] },
    { "id": 51000000002, "created_at": "2026-09-13T14:01:00Z", "conclusion": "failure",
      "event": "pull_request", "head_sha": "bbb", "pull_requests": [ { "number": 409 } ] },
    { "id": 51000000003, "created_at": "2026-09-13T14:02:00Z", "conclusion": "failure",
      "event": "pull_request", "head_sha": "ccc", "pull_requests": [] },
    { "id": 51000000004, "created_at": "2026-09-13T14:03:00Z", "conclusion": "success",
      "event": "pull_request", "head_sha": "ddd", "pull_requests": [ { "number": 388 } ] },
    { "id": 51000000005, "created_at": "2026-09-13T14:04:00Z", "conclusion": "failure",
      "event": "push", "head_sha": "eee", "pull_requests": [] }
  ] }
JSON
check "число считается ПО ПРЕДМЕТУ: письмо о #388 не считает отказы #409" "51000000001" \
  "$(notifier_mute_muted_ids "$SUBJ_JSON" '2026-09-13T13:00:00Z' 0 '#388')"
check "и письмо о #409 — своё" "51000000002" \
  "$(notifier_mute_muted_ids "$SUBJ_JSON" '2026-09-13T13:00:00Z' 0 '#409')"
check "ключ-имя считает только беспредметные прогоны" "51000000005" \
  "$(notifier_mute_muted_ids "$SUBJ_JSON" '2026-09-13T13:00:00Z' 0 '')"
check "предмет-голова считает свой прогон" "51000000003" \
  "$(notifier_mute_muted_ids "$SUBJ_JSON" '2026-09-13T13:00:00Z' 0 '@ccc')"
# НЕРАЗРЕШЁННЫЙ ПРЕДМЕТ НЕ ПРОГЛАТЫВАЕТСЯ: прогон 51000000003 — событие
# `pull_request`, номера в выдаче нет. Он МОЖЕТ быть про #388, и отличить его
# нечем, поэтому в число он не вошёл, но назван числом неразличимых.
check "прогон с неразрешённым предметом назван, а не проглочен" "1" \
  "$(notifier_mute_ambiguous "$SUBJ_JSON" '2026-09-13T13:00:00Z' 0 '#388')"
# Два РАЗНЫХ номера различимы точно — неразличимости они не создают.
# И симметрично: у прогона-с-головой неразличимы оба номерных — за его головой
# мог стоять любой из них.
check "у предмета-головы неразличимы номерные прогоны" "2" \
  "$(notifier_mute_ambiguous "$SUBJ_JSON" '2026-09-13T13:00:00Z' 0 '@ccc')"
# У КЛЮЧА-ИМЕНИ НЕРАЗЛИЧИМЫХ НЕТ ВОВСЕ — пустой предмет значит «PR тут нет по
# построению события», а не «номер не прочитался». Это и есть доказательство,
# что `Comms Derived` правкой не тронут даже в счёте.
check "у ключа-имени неразличимых нет — пустой предмет это не «не прочитано»" "0" \
  "$(notifier_mute_ambiguous "$SUBJ_JSON" '2026-09-13T13:00:00Z' 0 '')"
# ПРЕДМЕТ — АРГУМЕНТ, А НЕ УМОЛЧАНИЕ: забытый четвёртый аргумент отказывает по
# имени, а не считает по чужому ключу. Пустая строка — законное значение, и
# именно поэтому `${4:?}` здесь не годится.
check "предмет забыли — отказ по имени (код 2), а не счёт по чужому ключу" "код 2" \
  "$(rc_probe notifier_mute_muted_ids "$SUBJ_JSON" '2026-09-13T13:00:00Z' 0)"
check "то же у счёта неразличимых" "код 2" \
  "$(rc_probe notifier_mute_ambiguous "$SUBJ_JSON" '2026-09-13T13:00:00Z' 0)"

# --- 16. СТРОКА ПИСЬМА НАЗЫВАЕТ ТОТ КЛЮЧ, ПО КОТОРОМУ ГЛУШИЛИ ------------------
#
# Число, названное читателю не тем ключом, по которому глушат, запрещено самим
# `notifier-mute.sh`. Проверяется текст, который увидит читатель треда.
# Ключ-имя: число ТОЧНОЕ, строка ровно прежней формы — `Comms Derived` правкой
# не тронут и здесь.
check "письмо с ключом-именем называет свой ключ и считает по нему точно" \
  '🔇 **Заглушено с прошлого письма (`2026-09-13T13:00:00Z`) отказов с тем же ключом `Claude PR Review`: 1** — прогоны 51000000005 (2026-09-13T14:04:00Z). У каждого прогона названо его собственное время: хвост считается с прошлого письма, а не с начала этой аварии, и относиться к ней не обязан. Правило — окно 900 с по ключу «имя уведомителя + предмет прогона» (`.github/scripts/notifier-mute.sh`).' \
  "$(muted_line ok "$SUBJ_JSON" '2026-09-13T13:00:00Z' 0 '')"
# А письмо о #409 не считает отказ #388 — это и есть дефект 198, закрытый в
# числе: ДО правки здесь стояло бы 3 (все отказы воркфлоу), теперь 1.
check "письмо о предмете не считает числом отказы ЧУЖОГО предмета" "нет" \
  "$(out_probe muted_line ok "$SUBJ_JSON" '2026-09-13T13:00:00Z' 0 '#409' -- -F '51000000001')"
# И НИЖНЯЯ ГРАНИЦА ОТ НЕРАЗЛИЧИМОСТИ — вторая причина той же формы «НЕ МЕНЕЕ»,
# названная своим текстом, а не подменённая причиной обрыва страницы.
check "неразличимый прогон опускает число до нижней границы и назван причиной" \
  '🔇 **Заглушено с прошлого письма (`2026-09-13T13:00:00Z`) отказов с тем же ключом `Claude PR Review #388`: НЕ МЕНЕЕ 1** — прогоны 51000000001 (2026-09-13T14:00:00Z). У каждого прогона названо его собственное время: хвост считается с прошлого письма, а не с начала этой аварии, и относиться к ней не обязан. Это НИЖНЯЯ ГРАНИЦА, а не число: у 1 отказных прогонов предмет не разрешился, и отличить их от ключа `Claude PR Review #388` нечем — в число они не вошли. Правило — окно 900 с по ключу «имя уведомителя + предмет прогона» (`.github/scripts/notifier-mute.sh`).' \
  "$(muted_line ok "$SUBJ_JSON" '2026-09-13T13:00:00Z' 0 '#388')"
# Маркер в теле письма несёт ПОЛНЫЙ ключ — иначе следующий прогон найдёт его
# письмом о другом предмете.
check "ветвь громкости не называет ключом одно имя, когда предмет есть" "нет" \
  "$(out_probe muted_line ok "$SUBJ_JSON" '2026-09-13T13:00:00Z' 0 '#388' -- -F 'ключом `Claude PR Review`')"

# --- 17. ХВОСТ НЕ ПРИПИСЫВАЕТСЯ ТЕКУЩЕЙ АВАРИИ (тред 198, случай 3) ----------
#
# ПЕРВОИСТОЧНИК — поле, а не выдумка: письмо смотрителя 2026-09-13T16:28:49Z
# напечатало «Заглушено с прошлого письма (2026-09-13T13:15:46Z) отказов того же
# уведомителя: 2 — прогоны 34759515483, 34759487215», и оба номера принадлежали
# ПРОШЛОЙ аварии (разбор 13.09, тред 180). У номеров стояло только число, а
# единственная дата рядом — дата аварии из заголовка письма: отнесение, которого
# никто не мерил, сообщалось читателю самой формой строки.
#
# Фикстура повторяет ФОРМУ случая, а не его секунды: два заглушённых прогона
# сразу за прошлым письмом и текущий отказ через три с лишним часа. Хвост
# считается с прошлого ПИСЬМА и границы аварии не знает по построению — значит
# проверяется не «отсёк ли он чужое», а «читаемо ли отнесение».
TAIL_JSON="$DIR/tail.json"
cat > "$TAIL_JSON" <<'JSON'
{ "total_count": 3,
  "workflow_runs": [
    { "id": 34760000000, "created_at": "2026-09-13T16:28:49Z", "conclusion": "failure" },
    { "id": 34759515483, "created_at": "2026-09-13T13:16:20Z", "conclusion": "failure" },
    { "id": 34759487215, "created_at": "2026-09-13T13:15:49Z", "conclusion": "failure" }
  ] }
JSON
check "хвост из ПРОШЛОЙ аварии читается по временам, а не по заголовку письма" \
  '🔇 **Заглушено с прошлого письма (`2026-09-13T13:15:46Z`) отказов с тем же ключом `Claude PR Review`: 2** — прогоны 34759515483 (2026-09-13T13:16:20Z), 34759487215 (2026-09-13T13:15:49Z). У каждого прогона названо его собственное время: хвост считается с прошлого письма, а не с начала этой аварии, и относиться к ней не обязан. Правило — окно 900 с по ключу «имя уведомителя + предмет прогона» (`.github/scripts/notifier-mute.sh`).' \
  "$(muted_line ok "$TAIL_JSON" '2026-09-13T13:15:46Z' 34760000000)"
# КОНТРОЛЬ МУТАЦИИ: прежнее поведение на ТОМ ЖЕ входе — голые числа. Проверяется
# подстрокой ровно той формы, которую печатала строка до этой правки; найдись
# она — правка не доехала, как бы ни выглядело остальное.
check "мутация: прежняя форма (голые номера) на том же входе — её больше нет" "нет" \
  "$(grep_probe "$(muted_line ok "$TAIL_JSON" '2026-09-13T13:15:46Z' 34760000000)" \
     -F 'прогоны 34759515483, 34759487215')"
# ОБРАТНАЯ СТОРОНА. У выбранной формы (времена у каждого номера) ветвления по
# возрасту нет вовсе — и это её главное свойство: хвост, целиком лежащий ВНУТРИ
# текущей аварии, печатается тем же способом, а не «упрощается» до чисел.
# Отвергнутая вторая форма (отдельная строка «к этой аварии не относится») этой
# сверкой и отличалась бы: ей понадобилась бы граница аварии, которой нет.
INSIDE_JSON="$DIR/tail-inside.json"
cat > "$INSIDE_JSON" <<'JSON'
{ "total_count": 3,
  "workflow_runs": [
    { "id": 34760000000, "created_at": "2026-09-13T16:28:49Z", "conclusion": "failure" },
    { "id": 34760000002, "created_at": "2026-09-13T16:28:10Z", "conclusion": "failure" },
    { "id": 34760000001, "created_at": "2026-09-13T16:27:35Z", "conclusion": "failure" }
  ] }
JSON
check "хвост ЦЕЛИКОМ внутри текущей аварии печатается той же формой" \
  '🔇 **Заглушено с прошлого письма (`2026-09-13T16:27:00Z`) отказов с тем же ключом `Claude PR Review`: 2** — прогоны 34760000002 (2026-09-13T16:28:10Z), 34760000001 (2026-09-13T16:27:35Z). У каждого прогона названо его собственное время: хвост считается с прошлого письма, а не с начала этой аварии, и относиться к ней не обязан. Правило — окно 900 с по ключу «имя уведомителя + предмет прогона» (`.github/scripts/notifier-mute.sh`).' \
  "$(muted_line ok "$INSIDE_JSON" '2026-09-13T16:27:00Z' 34760000000)"
# ВРЕМЯ НЕ ПРОЧИТАНО — НЕ ГОЛОЕ ЧИСЛО. Ветвь обязана сказать это словами и не
# уронить письмо: голое число здесь было бы чинимым дефектом ровно там, где его
# никто не ждёт, а упавшее письмо — тишиной в аварии (дефект треда 073).
#
# ПРЕДИКАТ ВРЕМЕНИ ПОДМЕНЁН ОТКАЗОМ, И ЭТО ЕДИНСТВЕННЫЙ СПОСОБ ДОЙТИ ДО ВЕТВИ:
# номер отбирается и время читается по ОДНОМУ ответу, причём сам отбор требует
# `created_at` (`select(.created_at > $last_at)`), — значит данными эта ветвь
# недостижима, и фикстура «прогон без времени» проверяла бы не её, а отбор.
# Подмена живёт в подоболочке сверки и на остальные сверки не действует.
check "время не прочитано — сказано словами, письмо не упало, счёт цел" \
  '🔇 **Заглушено с прошлого письма (`2026-09-13T13:15:46Z`) отказов с тем же ключом `Claude PR Review`: 2** — прогоны 34759515483 (время не прочитано), 34759487215 (время не прочитано). У каждого прогона названо его собственное время: хвост считается с прошлого письма, а не с начала этой аварии, и относиться к ней не обязан. Правило — окно 900 с по ключу «имя уведомителя + предмет прогона» (`.github/scripts/notifier-mute.sh`).' \
  "$( notifier_mute_muted_at() { return 5; }; muted_line ok "$TAIL_JSON" '2026-09-13T13:15:46Z' 34760000000 )"
# И подмена правда снята: та же сверка на том же входе снова даёт времена.
check "подмена предиката осталась в своей подоболочке" "да" \
  "$(grep_probe "$(muted_line ok "$TAIL_JSON" '2026-09-13T13:15:46Z' 34760000000)" \
     -F '34759515483 (2026-09-13T13:16:20Z)')"
# И ТЕЛО ВЕТВИ ПРАВДА ЗОВЁТ ПРЕДИКАТ ВРЕМЕНИ — иначе три сверки выше зеленели бы
# на строке, собранной в самом воркфлоу мимо `notifier-mute.sh`.
check "тело ветви вырезано из notifier-watch.yml: предикат времени на месте" "да" \
  "$(file_probe -F 'notifier_mute_muted_at' "$BLOCK")"

if [ "$FAILED" = 0 ]; then
  echo "правило глушения: все проверки прошли"
else
  echo "правило глушения: ЕСТЬ ОТКАЗЫ"
fi
exit "$FAILED"
